def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less than 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    # Handle edge cases
    if a < 2:
        return False

    # Generate all primes up to 100 using Sieve of Eratosthenes
    def sieve_of_eratosthenes(limit):
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False

        for i in range(2, int(limit**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, limit + 1, i):
                    is_prime[j] = False

        return [i for i in range(2, limit + 1) if is_prime[i]]

    primes = sieve_of_eratosthenes(100)
    prime_set = set(primes)

    # Function to get prime factorization with multiplicity
    def prime_factorization(n):
        factors = []
        temp = n

        for p in primes:
            if p * p > temp:
                break
            while temp % p == 0:
                factors.append(p)
                temp //= p

        # If temp > 1, then it's a prime factor
        if temp > 1:
            factors.append(temp)

        return factors

    # Get the prime factorization of a
    factors = prime_factorization(a)

    # Check if the total number of prime factors (with multiplicity) is exactly 3
    if len(factors) != 3:
        return False

    # Verify that all factors are prime (should be true due to algorithm, but good to check)
    for factor in factors:
        if factor not in prime_set:
            return False

    return True

