def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Step 1: Check for whitespace and split if present
    if ' ' in txt:
        return txt.split()

    # Step 2: If no whitespace, check for commas and split if present
    if ',' in txt:
        return txt.split(',')

    # Step 3: If neither whitespace nor commas, count lowercase letters with odd alphabetical position
    # Alphabetical position: 'a' -> 0, 'b' -> 1, ..., 'z' -> 25
    # We want letters where position % 2 == 1 (odd positions)
    count = 0
    for char in txt:
        if char.islower() and char.isalpha():
            pos = ord(char) - ord('a')  # 0 for 'a', 1 for 'b', etc.
            if pos % 2 == 1:
                count += 1

    return count

